"""短链跳转一级决策：按 route 快照里的规则求值，再编译出这次点击的去向。"""

from datetime import datetime


def decide(config, now, ua, device, province):
    if config is None:
        return {"http": 404}
    if config.get("status", 0) != 0:
        return {"http": 403}
    expire = _to_dt(config.get("expire_time"))
    moment = _to_dt(now)
    if expire is not None and moment is not None and moment > expire:
        return {"http": 410}
    for rule in _ordered(config.get("rules")):
        if not _matches(rule, now, ua, device, province):
            continue
        target = _compile(rule)
        if target is not None:
            return target
    return {"http": 500}


def _ordered(rules):
    if not rules:
        return []
    return sorted(rules, key=_priority)


def _priority(rule):
    try:
        return int(rule.get("priority"))
    except (TypeError, ValueError):
        return 0


def _matches(rule, now, ua, device, province):
    ctype = _text(rule.get("condition_type")).lower()
    if ctype == "ua_container":
        return _value_hit(rule, _container(ua))
    if ctype == "device":
        return _value_hit(rule, _text(device))
    if ctype == "geo_province":
        return _value_hit(rule, _text(province))
    if ctype == "time_window":
        return _time_window(rule, now)
    if ctype == "default":
        return True
    return False


def _container(ua):
    raw = _text(ua).lower()
    if not raw:
        return ""
    for token, key in (("micromessenger", "wx"), ("mqqbrowser", "qq"), ("weibo", "weibo")):
        if token in raw:
            return key
    return "unknown"


def _value_hit(rule, actual):
    if not actual:
        return False
    want = _text(rule.get("condition_value")).lower()
    op = _text(rule.get("condition_op")).lower()
    target = actual.lower()
    if op == "eq":
        return want == target
    if op == "in":
        return any(one.strip() == target for one in want.split(","))
    return False


def _time_window(rule, now):
    bounds = _split_range(rule.get("condition_value"))
    today = _to_date(now)
    if bounds is None or today is None:
        return False
    start, end = bounds
    return start <= today < end


def _split_range(raw):
    body = _text(raw).strip("[]")
    if not body:
        return None
    parts = [one.strip().strip("\"'") for one in body.split(",")]
    if len(parts) != 2:
        return None
    start, end = _to_date(parts[0]), _to_date(parts[1])
    if start is None or end is None:
        return None
    return start, end


def _compile(rule):
    kind = _text(rule.get("target_type")).lower()
    url = _text(rule.get("target_url"))
    scheme = _text(rule.get("scheme_url"))
    fallback = _text(rule.get("fallback_url"))
    if kind == "h5":
        return {"type": "h5", "url": url} if url else None
    if kind == "intermediate":
        return {"type": "intermediate", "url": url} if url else None
    if kind == "app_scheme":
        if not scheme or not fallback:
            return None
        return {"type": "app_scheme", "scheme": scheme, "fallback": fallback}
    if kind == "wx_urllink":
        if not url or not scheme:
            return None
        return {"type": "wx_urllink", "url": url, "path": scheme}
    return None


def _to_dt(value):
    if isinstance(value, datetime):
        return value
    text = _text(value)
    if not text:
        return None
    try:
        return datetime.fromisoformat(text)
    except ValueError:
        return None


def _to_date(value):
    moment = _to_dt(value)
    return moment.date() if moment is not None else None


def _text(value):
    return "" if value is None else str(value).strip()

